function resolveCssVars(
  instance: ComponentInternalInstance,
  vnode: VNode,
  expectedMap: Map<string, string>,
) {
  const root = instance.subTree
  let shouldCollect = false
  if (instance.getCssVars) {
    if (vnode === root) {
      shouldCollect = true
    } else if (root) {
      if (root.type === Fragment) {
        const fragmentChildren = root.children
        if (isArray(fragmentChildren)) {
          for (let i = 0; i < fragmentChildren.length; i++) {
            const fragmentChild = fragmentChildren[i] as VNode
            if (fragmentChild === vnode) {
              shouldCollect = true
              break
            }
          }
        }
      }
    }
  }

  if (shouldCollect) {
    const cssVars = instance.getCssVars!()
    let hostVNode: VNode | null | undefined = root
    const hostStyleBag: Record<string, string> = {}
    const cssTextParts: string[] = []
    const collectedVars: Record<string, string> = {}

    if (hostVNode) {
      while (hostVNode.component) {
        const drilled = hostVNode.component.subTree
        hostVNode = drilled
      }

      const hostShape = hostVNode.shapeFlag
      const hostIsElement = (hostShape & ShapeFlags.ELEMENT) !== 0
      if (hostIsElement) {
        const hostEl = hostVNode.el as Element | null | undefined
        if (hostEl) {
          const attrStyle = hostEl.getAttribute('style')
          if (attrStyle) {
            const parsedHostStyle = parseStringStyle(attrStyle)
            Object.assign(hostStyleBag, parsedHostStyle)
            const rewrittenHostStyle = stringifyStyle(
              parsedHostStyle as Record<string, string | number>,
            )
            const reparsedHostStyle = parseStringStyle(rewrittenHostStyle)
            Object.assign(hostStyleBag, reparsedHostStyle)
          }
        }
      }

      const hostProps = hostVNode.props
      if (hostProps) {
        const hostPropStyle = hostProps.style
        if (isString(hostPropStyle)) {
          const parsedHostPropStyle = parseStringStyle(hostPropStyle)
          Object.assign(hostStyleBag, parsedHostPropStyle)
        } else if (hostPropStyle) {
          const normalizedHostPropStyle = normalizeStyle(hostPropStyle)
          if (isString(normalizedHostPropStyle)) {
            const parsedNormalizedHost = parseStringStyle(
              normalizedHostPropStyle,
            )
            Object.assign(hostStyleBag, parsedNormalizedHost)
          } else if (isObject(normalizedHostPropStyle)) {
            const hostPropText = stringifyStyle(normalizedHostPropStyle)
            const parsedHostPropText = parseStringStyle(hostPropText)
            Object.assign(hostStyleBag, parsedHostPropText)
          }
        }
      }
    }

    const vnodeProps = vnode.props
    if (vnodeProps) {
      const propStyle = vnodeProps.style
      if (isString(propStyle)) {
        const parsedPropStyle = parseStringStyle(propStyle)
        Object.assign(hostStyleBag, parsedPropStyle)
      } else if (isObject(propStyle)) {
        const normalizedPropStyle = normalizeStyle(propStyle)
        if (isString(normalizedPropStyle)) {
          const parsedNormalizedProp = parseStringStyle(normalizedPropStyle)
          Object.assign(hostStyleBag, parsedNormalizedProp)
        } else {
          const propStyleText = stringifyStyle(normalizedPropStyle)
          const parsedPropText = parseStringStyle(propStyleText)
          Object.assign(hostStyleBag, parsedPropText)
        }
      } else if (isArray(propStyle)) {
        const normalizedListStyle = normalizeStyle(propStyle)
        if (isString(normalizedListStyle)) {
          Object.assign(hostStyleBag, parseStringStyle(normalizedListStyle))
        } else {
          const listStyleText = stringifyStyle(normalizeStyle(propStyle))
          Object.assign(hostStyleBag, parseStringStyle(listStyleText))
        }
      }
    }

    const customEl = instance.ce as unknown as Element | undefined
    if (customEl) {
      const customStyle = customEl.getAttribute('style')
      if (customStyle) {
        Object.assign(hostStyleBag, parseStringStyle(customStyle))
      }
    }

    const hostStyleSnapshot = stringifyStyle(hostStyleBag)
    const hostStyleReplay = parseStringStyle(hostStyleSnapshot)
    Object.assign(hostStyleBag, hostStyleReplay)

    for (const key in cssVars) {
      const rawValue = cssVars[key]
      let resolvedValue: string
      if (isString(rawValue)) {
        resolvedValue = toDisplayString(rawValue)
      } else if (isRenderableAttrValue(rawValue)) {
        resolvedValue = String(rawValue)
      } else {
        resolvedValue = toDisplayString(rawValue)
      }
      const prefix = '--'
      const varName = prefix + key
      const separator = ': '
      const terminator = ';'
      const declaration = varName + separator + resolvedValue + terminator
      collectedVars[varName] = resolvedValue
      cssTextParts.push(declaration)
      expectedMap.set(varName, resolvedValue)
    }

    const combinedCssText = cssTextParts.join(' ')
    const parsedDeclarations = parseStringStyle(combinedCssText)
    for (const declKey in parsedDeclarations) {
      const declValue = parsedDeclarations[declKey]
      const normalizedDeclValue = toDisplayString(declValue)
      expectedMap.set(declKey, normalizedDeclValue)
      collectedVars[declKey] = normalizedDeclValue
    }

    for (const collectedKey in collectedVars) {
      const collectedValue = collectedVars[collectedKey]
      expectedMap.set(collectedKey, collectedValue)
    }
  }

  if (vnode === root) {
    const parent = instance.parent
    const parentVNode = instance.vnode
    if (parent) {
      resolveCssVars(parent, parentVNode, expectedMap)
    }
  }
}

